-- N4 example sentences, batch 3: guessing, quoting, and doing things for people.
--
-- 〜かもしれない, 〜だろう, 〜と思う, 〜という, 〜かどうか, then the five
-- auxiliary verbs that ride on 〜て: あげる, くれる, もらう, おく, しまう.
--
-- The auxiliaries came with a constraint worth writing down. あげる, くれる,
-- もらう and the aspectual おく and しまう are in the vocabulary as dictionary
-- forms only — the index holds spellings, not conjugations, and it de-inflects
-- kanji-stemmed verbs (読んで, 教えて, 撮って all cut clean) but not kana-only
-- ones. So 読んであげました shredded to 読んで | あ | げ | ました, and so did
-- あげた, あげたい, くれます, くれた, もらいました, おきます and しまった.
--
-- What survives is あげる, くれる, もらう, おく, おいて, しまう and
-- しまいました. Those five topics are therefore written in plain form, which
-- is what their patterns show anyway — Verb-て + あげる, not + あげました.
-- Not a lexicon fix worth making from a seed; the giving verbs want proper
-- entries and that is a vocabulary import, not four example sentences.
--
-- One other rewording: 明日雨が降るかどうか… left 雨 with no ruby, the same
-- aligner gap batch 1 hit behind 昨日. 雨 opens the sentence instead.
--
-- Additive, idempotent, safe on a live database.

  -- kamoshirenai
  ('sent-ex-kamo-1', 'lang-ja', '明日は雨が降るかもしれません。', 'あした わ あめ が ふる かもしれません。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-kamo-2', 'lang-ja', '先生は来ないかもしれない。', 'せんせい わ こない かもしれない。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-kamo-3', 'lang-ja', '試験は難しいかもしれません。', 'しけん わ むずかしい かもしれません。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-kamo-4', 'lang-ja', '兄はもう帰ったかもしれない。', 'あに わ もう かえった かもしれない。', 'lvl-ja-n4', 'authored', true),
  -- darou
  ('sent-ex-darou-1', 'lang-ja', '明日は寒いでしょう。', 'あした わ さむい でしょう。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-darou-2', 'lang-ja', 'あの店は高いだろう。', 'あの みせ わ たかい だろう。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-darou-3', 'lang-ja', '先生はもう来るでしょう。', 'せんせい わ もう くる でしょう。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-darou-4', 'lang-ja', '今夜は雪が降るだろう。', 'こんや わ ゆき が ふる だろう。', 'lvl-ja-n4', 'authored', true),
  -- to-omou
  ('sent-ex-toomou-1', 'lang-ja', '明日は雨が降ると思います。', 'あした わ あめ が ふる と おもいます。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-toomou-2', 'lang-ja', 'あの映画は面白いと思う。', 'あの えいが わ おもしろい と おもう。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-toomou-3', 'lang-ja', '日本へ行こうと思います。', 'にほん え いこう と おもいます。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-toomou-4', 'lang-ja', '先生は来ないと思います。', 'せんせい わ こない と おもいます。', 'lvl-ja-n4', 'authored', true),
  -- to-iu
  ('sent-ex-toiu-1', 'lang-ja', '桜という花を知っていますか。', 'さくら という はな お しって います か。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-toiu-2', 'lang-ja', 'あれは何という店ですか。', 'あれ わ なん という みせ です か。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-toiu-3', 'lang-ja', '花見という言葉を習いました。', 'はなみ という ことば お ならいました。', 'lvl-ja-n4', 'authored', true),
  ('sent-ex-toiu-4', 'lang-ja', '兄が来ないという話を聞いた。', 'あに が こない という はなし お きいた。', 'lvl-ja-n4', 'authored', true),
